	private Value seed(SailRepository repository, boolean storedRightHandRow) {
		Resource subject = repository.getValueFactory().createIRI("urn:entry:subject");
		var predicate = repository.getValueFactory().createIRI("urn:entry:p");
		var optionalPredicate = repository.getValueFactory().createIRI("urn:entry:q");
		var storedOptionalValue = repository.getValueFactory().createIRI("urn:entry:stored");
		try (var connection = repository.getConnection()) {
			connection.add(subject, predicate, repository.getValueFactory().createLiteral("owned"));
			if (storedRightHandRow) {
				connection.add(subject, optionalPredicate, storedOptionalValue);
			}
		}
		return subject;
	}

